package main

import "testing"

// The juniper_mx10004 chassis gained a second Routing Engine. Its
// jnxOperating rows (descr, 1-minute and 5-minute load average at index
// 9.2.0.0) are the only shipped SNMP rows this change added; the tables
// below were machine-generated by diffing the profile at the parent
// revision against this change and are committed verbatim.

// mx10004DualREParentRevision is the revision the two golden digests below
// were taken at: the branch commit before this change.
const mx10004DualREParentRevision = "c0a806c"

const (
	shippedTagDigestBeforeMx10004DualRE         = "3003c79f424bfe3a7d9ca3888ecef2fc7a563fc466f79742ad216fa9e2aa2cb4"
	shippedOIDEncodingDigestBeforeMx10004DualRE = "c72b443dc6468e7b1c214aae0404cb435230ba656cf3a9295bec9fc71e9d506a"
)

var mx10004DualREEdits = []profileRowEdit{
	{op: editAdd, oid: ".1.3.6.1.4.1.2636.3.1.13.1.5.9.2.0.0", after: "Routing Engine 1"},
	{op: editAdd, oid: ".1.3.6.1.4.1.2636.3.1.13.1.20.9.2.0.0", after: "3"},
	{op: editAdd, oid: ".1.3.6.1.4.1.2636.3.1.13.1.21.9.2.0.0", after: "4"},
}

var mx10004DualREAddedOIDNames = []string{"1.3.6.1.4.1.2636.3.1.13.1.20.9.2.0.0", "1.3.6.1.4.1.2636.3.1.13.1.21.9.2.0.0", "1.3.6.1.4.1.2636.3.1.13.1.5.9.2.0.0"}

var mx10004DualRERemovedOIDNames = []string{}

func restoreMx10004DualRE(t *testing.T, cur map[[2]string]string) {
	t.Helper()
	reverseProfileEdits(t, cur, juniperMx10004Profile, "juniper_mx10004 dual RE", mx10004DualREEdits)
}

func mx10004DualREOIDNamesBefore(t *testing.T, names []string) []string {
	t.Helper()
	return reverseOIDNameEdits(t, names, "juniper_mx10004 dual RE", mx10004DualREAddedOIDNames, mx10004DualRERemovedOIDNames)
}

func TestMx10004DualREReproducesTheParentCorpus(t *testing.T) {
	if got := corpusTagDigest(t, corpusValuesAt(t, mx10004DualREParentRevision)); got != shippedTagDigestBeforeMx10004DualRE {
		t.Errorf("reversing the dual-RE change gives digest %s, want %s: another shipped row changed without being recorded",
			got, shippedTagDigestBeforeMx10004DualRE)
	}
}

func TestMx10004DualRERePinIsOnlyTheEdit(t *testing.T) {
	restored := restoreCorpusOIDNamesTo(t, collectShippedOIDs(t), mx10004DualREParentRevision)
	if got := corpusOIDNameDigest(restored); got != shippedOIDEncodingDigestBeforeMx10004DualRE {
		t.Errorf("reversing the dual-RE OID names gives digest %s, want %s", got, shippedOIDEncodingDigestBeforeMx10004DualRE)
	}
}
